    right = qubit.new_at(0, 4, 0)
    free = squin.qalloc(1)

    squin.broadcast.h(ilist.IList([left, right]))
    squin.cx(left, free[0])
    return squin.broadcast.measure(ilist.IList([left, right, free[0]]))
